CREATE OR REPLACE FUNCTION public.listing_public_offer_floor(p_listing uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select t.offer_floor_cents
  from public.listings l
  join public.listing_private_terms t on t.listing_id = l.id
  where l.id = p_listing
    and l.show_offer_floor
    and l.status in ('active', 'reserved', 'sold')
    and (l.seller_id = (select auth.uid()) or not (l.seller_id in (select public.suspended_profile_ids())));
$function$;

comment on function public.listing_public_offer_floor(p_listing uuid) is 'A listing''s offer minimum, only when its seller chose to show it (O-3); null otherwise.';

grant execute on function public.listing_public_offer_floor(p_listing uuid) to anon;
grant execute on function public.listing_public_offer_floor(p_listing uuid) to authenticated;
grant execute on function public.listing_public_offer_floor(p_listing uuid) to service_role;
